115: function isSafeRoute(redirectUrl: string) {
116:   return Object.values(allowedRoutes).some(route => redirectUrl.includes(route));
117: }
118: 
119: /**
120:  * Get the current URL from the hash or pathname
121:  * Since we're using HashLocationStrategy, we need to extract the route from the hash
122:  */
123: function getCurrentUrlFromLocation(): string {
124:   // Check if we're using hash-based routing
125:   if (globalThis.location.hash) {
126:     // Extract the path after the # and remove the leading /
127:     const hashPath = globalThis.location.hash.substring(1); // Remove the #
128:     return hashPath.startsWith('/') ? hashPath.substring(1) : hashPath;
129:   }
130:   // Fallback to pathname if no hash
131:   const pathname = globalThis.location.pathname;
132:   return pathname.startsWith('/') ? pathname.substring(1) : pathname;
133: }
134: 
135: /**
136:  * shell and microfrontend are using different routers
137:  * when switching tabs, the shell is switching the URL, but the angular router of this microfrontend is not updated automatically
138:  */
139: function syncUrlWithRouter() {
140:   if (router) {
141:     const currentUrl = getCurrentUrlFromLocation();
142:     const normalizedRouterUrl = router.url.startsWith('/') ? router.url.substring(1) : router.url;
143: 
144:     if (normalizedRouterUrl !== currentUrl && isSafeRoute(currentUrl)) {
145:       router.navigateByUrl('/' + currentUrl).catch(err => console.error('Navigation Error:', err));
146:     }
147:   }
148: }
149: 
150: /**
151:  * Set up a listener for popstate events to sync the router when the shell changes the URL
152:  */
153: function setupRouterSync() {
154:   // Listen for hash changes (primary mechanism for HashLocationStrategy)
155:   globalThis.addEventListener('hashchange', () => {
156:     syncUrlWithRouter();
157:   });
158: 
159:   // Listen for browser navigation events (back/forward buttons)
160:   globalThis.addEventListener('popstate', () => {
161:     syncUrlWithRouter();
162:   });
163: }
164: 
165: export const bootstrap = bootstrapFn;
166: export const mount = lifecycles.mount;
167: export const unmount = lifecycles.unmount;

